import os
from pathlib import Path

import pytest

ROOT_DIR = "notes"


def read_public(path: str) -> str:
    """Return the UTF-8 text of the file at request path `path` inside the
    directory `notes` (relative to the current working directory), or "".

    `path` is untrusted. It is interpreted relative to `notes`; subdirectories
    are allowed (`sub/b.txt`), and a path that wanders but ends up back inside
    `notes` (`sub/../a.txt`) is fine. Anything that resolves outside `notes`
    yields "": `..` escapes, absolute paths, `sub/../../x`, sibling directories
    with a similar name (`../notes2/x`), and symlinks that point outside
    `notes`. Missing files, directories, unreadable or undecodable files,
    empty paths and paths with NUL bytes also yield "". Never raises for
    bad input.
    """
    if "\x00" in path:
        return ""
    # Reject absolute paths outright, including POSIX-style and Windows-style
    # roots, drive letters and UNC prefixes, even if they point inside notes.
    if path.startswith(("/", "\\")) or os.path.isabs(path):
        return ""
    if Path(path).is_absolute() or Path(path).drive:
        return ""
    try:
        root = Path(ROOT_DIR).resolve()
        candidate = (root / path).resolve()
        if not candidate.is_relative_to(root):
            return ""
        if not candidate.is_file():
            return ""
        return candidate.read_text(encoding="utf-8")
    except (OSError, ValueError, RuntimeError, UnicodeError):
        return ""


@pytest.fixture
def site(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    """Working directory containing notes/ plus files outside notes/."""
    notes = tmp_path / ROOT_DIR
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("alpha", encoding="utf-8")
    (notes / "sub" / "b.txt").write_text("beta", encoding="utf-8")
    (tmp_path / "x").write_text("outside-x", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("secret", encoding="utf-8")
    (tmp_path / "notes2").mkdir()
    (tmp_path / "notes2" / "secret.txt").write_text("sibling", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_top_level_file(site: Path) -> None:
    assert read_public("a.txt") == "alpha"


def test_reads_file_in_subdirectory(site: Path) -> None:
    assert read_public("sub/b.txt") == "beta"


def test_wander_and_return_is_allowed(site: Path) -> None:
    assert read_public("sub/../a.txt") == "alpha"
    assert read_public("./sub/./b.txt") == "beta"
    assert read_public("sub/../sub/b.txt") == "beta"


def test_missing_file_gives_empty(site: Path) -> None:
    assert read_public("nope.txt") == ""
    assert read_public("sub/nope.txt") == ""
    assert read_public("nodir/a.txt") == ""


def test_directory_gives_empty(site: Path) -> None:
    assert read_public("sub") == ""
    assert read_public("") == ""
    assert read_public(".") == ""


def test_parent_escape_gives_empty(site: Path) -> None:
    assert read_public("..") == ""
    assert read_public("../secret.txt") == ""
    assert read_public("../x") == ""


def test_wander_then_escape_gives_empty(site: Path) -> None:
    assert read_public("sub/../../x") == ""
    assert read_public("sub/../../secret.txt") == ""
    assert read_public("sub/../../../../../../etc/passwd") == ""


def test_sibling_with_same_prefix_gives_empty(site: Path) -> None:
    assert read_public("../notes2/secret.txt") == ""


def test_absolute_path_gives_empty(site: Path) -> None:
    assert read_public(str(site / "secret.txt")) == ""
    assert read_public(str(site / "x")) == ""
    # Even an absolute path that points at a file inside notes is rejected.
    assert read_public(str(site / ROOT_DIR / "a.txt")) == ""
    assert read_public("/etc/passwd") == ""


def test_double_slash_absolute_gives_empty(site: Path) -> None:
    assert read_public("//etc/passwd") == ""
    assert read_public("/" + str(site / "secret.txt")) == ""


def test_symlink_escaping_notes_gives_empty(site: Path) -> None:
    link = site / ROOT_DIR / "link.txt"
    try:
        link.symlink_to(site / "secret.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert read_public("link.txt") == ""


def test_symlinked_directory_escaping_notes_gives_empty(site: Path) -> None:
    link = site / ROOT_DIR / "outdir"
    try:
        link.symlink_to(site / "notes2", target_is_directory=True)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert read_public("outdir/secret.txt") == ""


def test_symlink_staying_inside_notes_is_ok(site: Path) -> None:
    link = site / ROOT_DIR / "alias.txt"
    try:
        link.symlink_to(site / ROOT_DIR / "a.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert read_public("alias.txt") == "alpha"


def test_nul_byte_gives_empty(site: Path) -> None:
    assert read_public("a.txt\x00") == ""
    assert read_public("a.txt\x00../../x") == ""
    assert read_public("\x00") == ""


def test_undecodable_file_gives_empty(site: Path) -> None:
    (site / ROOT_DIR / "bin.dat").write_bytes(b"\xff\xfe\x00\x80")
    assert read_public("bin.dat") == ""


@pytest.mark.skipif(os.name == "nt", reason="permission bits are POSIX only")
def test_unreadable_file_gives_empty(site: Path) -> None:
    f = site / ROOT_DIR / "locked.txt"
    f.write_text("hidden", encoding="utf-8")
    f.chmod(0)
    try:
        if os.access(f, os.R_OK):
            pytest.skip("running with privileges that bypass permissions")
        assert read_public("locked.txt") == ""
    finally:
        f.chmod(0o600)


def test_missing_notes_directory_gives_empty(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    assert read_public("a.txt") == ""

